// TSP_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module TSP_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_keep_tsc,
  input logic  c_pcr_en,
  input logic [12:0] c_pcr_pid,
  input logic [31:0] c_src_addr,
  input logic [15:0] c_pkts,
  input logic [31:0] c_outa_addr,
  input logic [15:0] c_outa_max,
  input logic [31:0] c_outb_addr,
  input logic [15:0] c_outb_max,
  input logic [1:0] c_slot,
  input logic  c_odd,
  input logic [31:0] c_key0,
  input logic [31:0] c_key1,
  input logic [31:0] c_key2,
  input logic [31:0] c_key3,
  input logic [12:0] c_slot_pid,
  input logic  c_slot_valid,
  input logic [1:0] c_slot_route,
  input logic  c_start,
  input logic  c_key_load,
  input logic  c_slot_load,
  input logic  c_busy,
  input logic  c_key_busy,
  input logic  c_err,
  input logic [15:0] c_a_cnt,
  input logic [15:0] c_b_cnt,
  input logic [15:0] c_desc_cnt,
  input logic [15:0] c_nokey_cnt,
  input logic [15:0] c_sync_cnt,
  input logic [15:0] c_drop_cnt,
  input logic [15:0] c_ovf_cnt,
  input logic [15:0] c_pkt_cnt,
  input logic [31:0] c_pcr_base,
  input logic [9:0] c_pcr_ext,
  input logic [31:0] c_pcr_local,
  input logic  c_done,
  input logic  c_err_irq,
  input logic  c_nokey,
  input logic  c_sync,
  input logic  c_pcr,
  input logic  c_ovf
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 28;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:27];          // model of every stored word
  logic [5:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_err_irq) m_set[1] = 1'b1;
    if (c_nokey) m_set[2] = 1'b1;
    if (c_sync) m_set[3] = 1'b1;
    if (c_pcr) m_set[4] = 1'b1;
    if (c_ovf) m_set[5] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'h7;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 16) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 17) m_w[17] <= ((m_w[17] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 18) m_w[18] <= ((m_w[18] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 19) ? PWDATA & m_be & 32'h7 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h7C0C0100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return 0;
      15: return 0;
      16: return 0;
      17: return 0;
      18: return m_w[18];
      19: return 0;
      20: return (32'(c_busy) << 0) | (32'(c_key_busy) << 1) | (32'(c_err) << 2);
      21: return (32'(c_a_cnt) << 0) | (32'(c_b_cnt) << 16);
      22: return (32'(c_desc_cnt) << 0) | (32'(c_nokey_cnt) << 16);
      23: return (32'(c_sync_cnt) << 0) | (32'(c_drop_cnt) << 16);
      24: return (32'(c_ovf_cnt) << 0) | (32'(c_pkt_cnt) << 16);
      25: return (32'(c_pcr_base) << 0);
      26: return (32'(c_pcr_ext) << 0);
      27: return (32'(c_pcr_local) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][5:0] & m_w[2][5:0]))
  `SVA_INV(a_core_keep_tsc, c_keep_tsc == m_w[5][0:0])
  `SVA_INV(a_core_pcr_en, c_pcr_en == m_w[5][1:1])
  `SVA_INV(a_core_pcr_pid, c_pcr_pid == m_w[6][12:0])
  `SVA_INV(a_core_src_addr, c_src_addr == m_w[7][31:0])
  `SVA_INV(a_core_pkts, c_pkts == m_w[8][15:0])
  `SVA_INV(a_core_outa_addr, c_outa_addr == m_w[9][31:0])
  `SVA_INV(a_core_outa_max, c_outa_max == m_w[10][15:0])
  `SVA_INV(a_core_outb_addr, c_outb_addr == m_w[11][31:0])
  `SVA_INV(a_core_outb_max, c_outb_max == m_w[12][15:0])
  `SVA_INV(a_core_slot, c_slot == m_w[13][1:0])
  `SVA_INV(a_core_odd, c_odd == m_w[13][2:2])
  `SVA_INV(a_core_key0, c_key0 == m_w[14][31:0])
  `SVA_INV(a_core_key1, c_key1 == m_w[15][31:0])
  `SVA_INV(a_core_key2, c_key2 == m_w[16][31:0])
  `SVA_INV(a_core_key3, c_key3 == m_w[17][31:0])
  `SVA_INV(a_core_slot_pid, c_slot_pid == m_w[18][12:0])
  `SVA_INV(a_core_slot_valid, c_slot_valid == m_w[18][13:13])
  `SVA_INV(a_core_slot_route, c_slot_route == m_w[18][15:14])
  `SVA_INV(a_core_start, c_start == m_pulse_CMD[0])
  `SVA_INV(a_core_key_load, c_key_load == m_pulse_CMD[1])
  `SVA_INV(a_core_slot_load, c_slot_load == m_pulse_CMD[2])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_keep_tsc == 1'h0 && c_pcr_en == 1'h0 && c_pcr_pid == 13'h0 && c_src_addr == 32'h0 && c_pkts == 16'h0 && c_outa_addr == 32'h0 && c_outa_max == 16'h0 && c_outb_addr == 32'h0 && c_outb_max == 16'h0 && c_slot == 2'h0 && c_odd == 1'h0 && c_key0 == 32'h0 && c_key1 == 32'h0 && c_key2 == 32'h0 && c_key3 == 32'h0 && c_slot_pid == 13'h0 && c_slot_valid == 1'h0 && c_slot_route == 2'h0 && c_start == 1'h0 && c_key_load == 1'h0 && c_slot_load == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_PCR_PID, m_rd && m_map && m_idx == 6)
  `FC(wr_PCR_PID, m_wr && m_map && m_idx == 6)
  `FC(rd_SRC_ADDR, m_rd && m_map && m_idx == 7)
  `FC(wr_SRC_ADDR, m_wr && m_map && m_idx == 7)
  `FC(rd_PKTS, m_rd && m_map && m_idx == 8)
  `FC(wr_PKTS, m_wr && m_map && m_idx == 8)
  `FC(rd_OUTA_ADDR, m_rd && m_map && m_idx == 9)
  `FC(wr_OUTA_ADDR, m_wr && m_map && m_idx == 9)
  `FC(rd_OUTA_MAX, m_rd && m_map && m_idx == 10)
  `FC(wr_OUTA_MAX, m_wr && m_map && m_idx == 10)
  `FC(rd_OUTB_ADDR, m_rd && m_map && m_idx == 11)
  `FC(wr_OUTB_ADDR, m_wr && m_map && m_idx == 11)
  `FC(rd_OUTB_MAX, m_rd && m_map && m_idx == 12)
  `FC(wr_OUTB_MAX, m_wr && m_map && m_idx == 12)
  `FC(rd_SLOT_SEL, m_rd && m_map && m_idx == 13)
  `FC(wr_SLOT_SEL, m_wr && m_map && m_idx == 13)
  `FC(rd_KEY0, m_rd && m_map && m_idx == 14)
  `FC(wr_KEY0, m_wr && m_map && m_idx == 14)
  `FC(rd_KEY1, m_rd && m_map && m_idx == 15)
  `FC(wr_KEY1, m_wr && m_map && m_idx == 15)
  `FC(rd_KEY2, m_rd && m_map && m_idx == 16)
  `FC(wr_KEY2, m_wr && m_map && m_idx == 16)
  `FC(rd_KEY3, m_rd && m_map && m_idx == 17)
  `FC(wr_KEY3, m_wr && m_map && m_idx == 17)
  `FC(rd_SLOT_CFG, m_rd && m_map && m_idx == 18)
  `FC(wr_SLOT_CFG, m_wr && m_map && m_idx == 18)
  `FC(rd_CMD, m_rd && m_map && m_idx == 19)
  `FC(wr_CMD, m_wr && m_map && m_idx == 19)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 20)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 20)
  `FC(rd_OUT_CNT, m_rd && m_map && m_idx == 21)
  `FC(wr_OUT_CNT, m_wr && m_map && m_idx == 21)
  `FC(rd_DESC_CNT, m_rd && m_map && m_idx == 22)
  `FC(wr_DESC_CNT, m_wr && m_map && m_idx == 22)
  `FC(rd_ERR_CNT, m_rd && m_map && m_idx == 23)
  `FC(wr_ERR_CNT, m_wr && m_map && m_idx == 23)
  `FC(rd_PKT_CNT, m_rd && m_map && m_idx == 24)
  `FC(wr_PKT_CNT, m_wr && m_map && m_idx == 24)
  `FC(rd_PCR_BASE, m_rd && m_map && m_idx == 25)
  `FC(wr_PCR_BASE, m_wr && m_map && m_idx == 25)
  `FC(rd_PCR_EXT, m_rd && m_map && m_idx == 26)
  `FC(wr_PCR_EXT, m_wr && m_map && m_idx == 26)
  `FC(rd_PCR_LOCAL, m_rd && m_map && m_idx == 27)
  `FC(wr_PCR_LOCAL, m_wr && m_map && m_idx == 27)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE_set, m_set[0])
  `FC(irq_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERR_set, m_set[1])
  `FC(irq_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_NOKEY_set, m_set[2])
  `FC(irq_NOKEY_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_NOKEY_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_NOKEY_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_SYNC_set, m_set[3])
  `FC(irq_SYNC_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_SYNC_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_SYNC_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_PCR_set, m_set[4])
  `FC(irq_PCR_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_PCR_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_PCR_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_OVF_set, m_set[5])
  `FC(irq_OVF_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_OVF_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_OVF_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(cmd_start, m_pulse_CMD[0])
  `FC(cmd_key_load, m_pulse_CMD[1])
  `FC(cmd_slot_load, m_pulse_CMD[2])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind TSP_apb TSP_apb_sva u_apb_sva (.*);
